INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Self-rental recharacterization rule
(6, 'Passive Activity and At-Risk Rules', 'Thornton, a sole proprietor, operates a restaurant through an S corporation. She also owns the building and rents it to the S corporation for $36,000 annually. Thornton materially participates in the restaurant but not in any other rental activities. Under the self-rental rule of Section 469, how is the $36,000 rental income treated?', '["The rental income is recharacterized as nonpassive income", "The rental income is treated as passive income that can offset other passive losses", "The rental income is treated as portfolio income", "The rental income is excluded from gross income as a related-party transaction"]'::jsonb, 0, 'Under IRC Section 469 and Treas. Reg. 1.469-2(f)(6), rental income from property rented to a business in which the taxpayer materially participates is recharacterized as nonpassive income. This self-rental rule prevents taxpayers from creating passive income to absorb passive losses from other activities. Choice B is incorrect because the self-rental rule specifically overrides the normal passive treatment of rental income when the property is rented to the taxpayer''s own materially-participated business.', 'medium', 2),

-- Q2: medium / L2 — PTP passive loss ring-fencing
(6, 'Passive Activity and At-Risk Rules', 'Nakamura owns a limited partnership interest in Ridgeline Energy Partners, a publicly traded partnership (PTP). During 2026, Ridgeline allocates $28,000 of passive losses to Nakamura. Nakamura also has $35,000 of passive income from a separate private real estate partnership. Under Section 469(k), how are Ridgeline''s passive losses treated?', '["The $28,000 loss offsets the $35,000 passive income from the real estate partnership, leaving $7,000 of net passive income", "The $28,000 loss is suspended and can only offset future passive income from Ridgeline Energy Partners", "The $28,000 loss can offset any passive income plus up to $25,000 of nonpassive income", "The $28,000 loss is permanently disallowed because publicly traded partnerships cannot generate deductible losses"]'::jsonb, 1, 'Under IRC Section 469(k), passive losses from a publicly traded partnership can only offset passive income from the same PTP. They cannot be netted against passive income from other activities. The $28,000 is suspended and carried forward for use against future Ridgeline income or released upon complete disposition. Choice A is incorrect because PTP losses are ring-fenced and cannot offset non-PTP passive income, even though both are classified as passive.', 'medium', 2),

-- Q3: easy / L1 — Definition of rental activity under Section 469
(6, 'Passive Activity and At-Risk Rules', 'Under Section 469, which of the following defines a rental activity?', '["An activity where customers pay primarily for the use of tangible property", "An activity that produces investment income from intangible assets", "Any activity in which the taxpayer does not materially participate", "An activity where services are the predominant source of revenue"]'::jsonb, 0, 'Under IRC Section 469(j)(8) and Treas. Reg. 1.469-1T(e)(3), a rental activity is one where payments are principally for the use of tangible property. Rental activities are generally treated as passive regardless of the taxpayer''s participation level. Choice D is incorrect because service-based activities are not rental activities; they are classified as trade or business activities subject to the material participation tests.', 'easy', 1),

-- Q4: hard / L3 — Installment sale of passive activity and suspended loss release
(6, 'Passive Activity and At-Risk Rules', 'Prescott sells his entire interest in a passive activity to an unrelated buyer on October 1, 2026, for $300,000. Prescott''s adjusted basis is $180,000, and he has $90,000 of suspended passive losses from the activity. The buyer pays $100,000 at closing and will pay $100,000 in each of the next two years. Prescott does not elect out of the installment method. Analyze how much of the suspended passive losses Prescott can deduct in the year of sale.', '["$90,000, because a complete disposition always releases all suspended losses immediately", "$0, because installment sales do not trigger suspended loss release until all payments are received", "$60,000, because suspended losses are released in proportion to the gain recognized each year", "$30,000, because only the gain recognized in the year of sale triggers a proportional release of suspended losses"]'::jsonb, 3, 'Under IRC Section 469(g)(3), when a passive activity is disposed of in an installment sale, suspended losses are allowed each year in the ratio that gain recognized bears to total gain. Total gain is $120,000. In year one, $40,000 is recognized (one-third), so $30,000 of suspended losses (one-third of $90,000) are released. Choice A is incorrect because Section 469(g)(3) modifies the general complete-disposition rule when the installment method applies, requiring proportional rather than immediate release.', 'hard', 3),

-- Q5: medium / L2 — MFS living together eliminates $25K allowance
(6, 'Passive Activity and At-Risk Rules', 'Patterson and her spouse file separate returns for 2026 and live together the entire year. Patterson actively participates in a rental property that generates a $20,000 loss. Her separate AGI is $75,000. What amount of the rental loss can Patterson deduct under the Section 469(i) special allowance?', '["$20,000, because her AGI is below the $100,000 phase-out threshold", "$0, because the special allowance is not available to married taxpayers filing separately who live together at any time during the year", "$10,000, because the allowance is reduced to $12,500 for married filing separately", "$12,500, because married-filing-separately taxpayers receive half the $25,000 allowance"]'::jsonb, 1, 'Under IRC Section 469(i)(5), a taxpayer who is married filing separately and lives with the spouse at any time during the year receives a $0 special allowance. This prevents income splitting to exploit the allowance twice. Choice D is incorrect because the reduced $12,500 allowance applies only to married-filing-separately taxpayers who live apart for the entire taxable year, not those who live together.', 'medium', 2),

-- Q6: easy / L2 — Working interest in oil and gas exception
(6, 'Passive Activity and At-Risk Rules', 'Calloway holds a direct working interest in a West Texas oil well through an LLC that does not limit her personal liability. During 2026, the oil well generates a $42,000 loss. Calloway does not materially participate in the oil well operations. Under the passive activity rules, how is the $42,000 loss treated?', '["As a passive loss that can only offset passive income", "As a suspended loss carried forward until Calloway materially participates", "As a portfolio loss that offsets portfolio income", "As a nonpassive loss that can offset Calloway''s other income"]'::jsonb, 3, 'Under IRC Section 469(c)(3), a working interest in oil and gas property held through a form that does not limit the taxpayer''s liability is not treated as a passive activity, regardless of participation level. The loss is therefore deductible against nonpassive income, subject to at-risk limitations. Choice A is incorrect because the oil and gas working interest exception specifically removes this activity from passive classification even without material participation.', 'easy', 2),

-- Q7: medium / L3 — Self-charged interest recharacterization
(6, 'Passive Activity and At-Risk Rules', 'Whitfield owns 100% of an S corporation that is a passive activity for her. During 2026, Whitfield lends $200,000 to the S corporation at 6% interest, receiving $12,000 of interest income. The S corporation generates a $50,000 passive loss. Under the self-charged interest rules of Treas. Reg. 1.469-7, analyze how the $12,000 interest income is treated.', '["The interest income is recharacterized as passive income to the extent of Whitfield''s allocable share of the S corporation''s interest deduction", "The interest income remains portfolio income because all interest is classified as portfolio income under Section 469", "The interest income is disregarded as a related-party transaction under Section 267", "The interest income is treated as nonpassive income but creates an additional passive deduction for the S corporation"]'::jsonb, 0, 'Under IRC Section 469 and Treas. Reg. 1.469-7, when a taxpayer lends money to a pass-through entity in which the taxpayer has a passive interest, the resulting interest income is recharacterized as passive income to the extent of the taxpayer''s share of the entity''s interest deduction. This prevents the mismatch of passive deductions and portfolio income. Choice B is incorrect because the self-charged interest rule overrides the general portfolio income classification when lending is between the taxpayer and a pass-through entity.', 'medium', 3),

-- Q8: medium / L3 — Significant participation activity income recharacterization
(6, 'Passive Activity and At-Risk Rules', 'Delgado participates for 250 hours in a consulting business (Activity M) and 300 hours in a retail business (Activity N) during 2026. She does not materially participate in either activity individually. Activity M generates $45,000 of income and Activity N generates $30,000 of income. Under the passive activity recharacterization rules, analyze how the net income from these significant participation activities is treated.', '["Both activities are passive, and the $75,000 total income is available to offset other passive losses", "The $75,000 of net income from significant participation activities is recharacterized as nonpassive income", "Only Activity N''s income is recharacterized because its hours exceed the 250-hour threshold", "The income remains passive but is subject to the 3.8% net investment income tax only"]'::jsonb, 1, 'Under IRC Section 469 and Treas. Reg. 1.469-2T(f)(2), net income from significant participation activities — those in which the taxpayer participates more than 100 hours but does not materially participate — is recharacterized as nonpassive income. Both activities exceed 100 hours and generate net income, so the combined $75,000 is nonpassive. Choice A is incorrect because the recharacterization rule prevents taxpayers from using passive income from significant participation activities to shelter passive losses from other activities.', 'medium', 3),

-- Q9: medium / L3 — Activity changes from nonpassive to passive; suspended loss and current income interaction
(6, 'Passive Activity and At-Risk Rules', 'Okafor materially participated in a restaurant business from 2019 through 2024, then reduced her involvement in 2025 and 2026 to only 80 hours per year. The activity generated $25,000 of passive losses in 2025, which were fully suspended. In 2026, the activity generates $40,000 of income. Because Okafor does not materially participate in 2026, analyze how the 2026 income and suspended losses interact.', '["The $40,000 is nonpassive income because the activity was previously nonpassive, and the $25,000 suspended loss remains suspended", "The $25,000 suspended loss is permanently disallowed because Okafor no longer materially participates", "The $40,000 is passive income, but the $25,000 loss can only offset income from other passive activities", "The $40,000 is passive income, and the $25,000 suspended loss offsets it, leaving $15,000 of net passive income"]'::jsonb, 3, 'Under IRC Section 469(d)(1), passive losses offset passive income. Because Okafor does not materially participate in 2026, the activity is passive and the $40,000 is passive income. The $25,000 of suspended losses offsets it, producing $15,000 of net passive income. Choice A is incorrect because income classification depends on the taxpayer''s current-year participation status, not the activity''s historical classification.', 'medium', 3),

-- Q10: medium / L2 — Short-term rental exception (average period ≤ 7 days)
(6, 'Passive Activity and At-Risk Rules', 'Brighton operates a beachfront vacation property through an LLC. During 2026, the property is rented for 200 separate bookings with an average rental period of 4.5 days per guest. Brighton spends 650 hours managing the property. Under Treas. Reg. 1.469-1T(e)(3)(ii), how is this activity classified?', '["As a trade or business activity, not a rental activity, because the average period of customer use is 7 days or less", "As a rental activity because the property is rented to customers for their use", "As a portfolio activity because short-term rentals produce investment income", "As a rental activity eligible for the $25,000 special allowance"]'::jsonb, 0, 'Under IRC Section 469 and Treas. Reg. 1.469-1T(e)(3)(ii)(A), an activity is not treated as a rental activity if the average period of customer use is 7 days or less. Because Brighton''s average rental is 4.5 days, the activity is a trade or business subject to material participation tests rather than rental activity rules. Choice B is incorrect because the short-term rental exception removes the activity from rental classification despite customers paying for property use.', 'medium', 2),

-- Q11: medium / L3 — Loss ordering: basis, at-risk, then passive
(6, 'Passive Activity and At-Risk Rules', 'Hargrove is a partner in Maple Creek Partnership, a passive activity. Her outside basis is $50,000, her at-risk amount is $35,000, and she has $20,000 of passive income from another activity. The partnership allocates $60,000 of losses to Hargrove. Analyze the order in which the loss limitation rules restrict her deduction and the final deductible amount.', '["$35,000 — the at-risk limitation applies first, then passive rules are irrelevant", "$60,000 — the passive income fully offsets the passive loss after netting", "$20,000 — basis limits the loss to $50,000, at-risk further limits it to $35,000, and passive rules allow only $20,000 against passive income", "$50,000 — basis is the only applicable limitation"]'::jsonb, 2, 'Under the three-tier loss limitation ordering, the basis limitation under IRC Section 704(d) applies first (limiting the loss to $50,000), then the at-risk rules under Section 465 further limit it to $35,000, and finally the passive activity rules under Section 469 allow only $20,000 to offset passive income. The remaining $15,000 is suspended under the passive rules. Choice D is incorrect because it ignores both the at-risk and passive activity limitations that apply after the basis limitation.', 'medium', 3),

-- Q12: easy / L1 — Activities subject to at-risk rules after 1978 expansion
(6, 'Passive Activity and At-Risk Rules', 'Under IRC Section 465(c), which activities are subject to the at-risk rules?', '["Only real estate rental activities", "Virtually all trade or business and income-producing activities", "Only activities conducted through partnerships and S corporations", "Only activities specifically listed in Section 465(c)(1), such as farming and oil exploration"]'::jsonb, 1, 'Under IRC Section 465(c)(3), the at-risk rules apply to virtually all activities engaged in by a taxpayer in carrying on a trade or business or for the production of income. While Section 465 originally applied only to enumerated activities like farming and film production, the 1978 expansion made the rules nearly universal. Choice D is incorrect because it reflects the pre-1978 law before Congress expanded at-risk coverage to substantially all activities.', 'easy', 1),

-- Q13: easy / L2 — At-risk amount restored by activity income
(6, 'Passive Activity and At-Risk Rules', 'Cooper invested $80,000 cash in a partnership activity in 2024. In 2025, the activity allocated $60,000 of losses to Cooper, reducing his at-risk amount to $20,000. In 2026, the activity allocates $35,000 of income to Cooper. What is Cooper''s at-risk amount at the end of 2026?', '["$20,000, because at-risk amounts cannot increase after being reduced by losses", "$80,000, because the income restores the at-risk amount to its original level", "$35,000, because income replaces losses dollar for dollar starting from zero", "$55,000, because the at-risk amount is increased by the taxpayer''s share of activity income"]'::jsonb, 3, 'Under IRC Section 465(b), a taxpayer''s at-risk amount increases by income allocated from the activity, just as it decreases from allocated losses. Cooper''s at-risk amount starts at $20,000 (after the 2025 loss) and increases by the $35,000 of 2026 income to $55,000. Choice A is incorrect because at-risk amounts are dynamic and increase with additional contributions, allocated income, and increases in qualifying debt.', 'easy', 2),

-- Q14: hard / L4 — Evaluate PTP disposition vs holding strategy
(6, 'Passive Activity and At-Risk Rules', 'A tax advisor is counseling Stein, who holds a publicly traded partnership interest with $65,000 of suspended passive losses. The PTP generates only $3,000 to $5,000 of annual passive income. Stein''s basis is $90,000 and the current market value is $110,000. Stein is in the 37% marginal bracket. Evaluate whether Stein should sell the PTP interest in 2026.', '["Hold the PTP because the annual income will eventually absorb all suspended losses", "Hold the PTP because selling would create a capital gain without releasing the suspended losses", "Sell the PTP because complete disposition releases all $65,000 of suspended losses, creating a net tax benefit despite the $20,000 gain", "Sell the PTP because suspended PTP losses convert to capital losses upon disposition"]'::jsonb, 2, 'Under IRC Section 469(g)(1), a fully taxable disposition to an unrelated party releases all suspended passive losses. The $20,000 gain is offset by $20,000 of suspended losses, and the remaining $45,000 offsets other income. At 37%, the net tax savings from releasing $45,000 in deductions ($16,650) outweighs the tax cost. Choice A is incorrect because at $3,000-$5,000 per year, absorbing $65,000 would take 13-22 years, making disposition the more tax-efficient strategy.', 'hard', 4),

-- Q15: easy / L2 — Passive loss carryforward indefinitely
(6, 'Passive Activity and At-Risk Rules', 'Fleming has $45,000 of passive losses from a rental activity and $30,000 of passive income from a partnership in 2026. Fleming does not actively participate in the rental. How much of the excess passive loss is carried forward?', '["$45,000, because rental losses cannot offset partnership income", "$15,000, because the excess of passive losses over passive income is suspended and carried forward indefinitely", "$0, because all passive losses expire at the end of the tax year if unused", "$25,000, because the special allowance absorbs the remaining loss"]'::jsonb, 1, 'Under IRC Section 469(b), passive losses exceeding passive income for the year are suspended and carried forward indefinitely to offset passive income in future years. Fleming''s $45,000 loss offsets $30,000 of passive income, and the remaining $15,000 is carried forward. Choice C is incorrect because passive losses never expire through the passage of time — they carry forward until absorbed by passive income or released upon a taxable disposition.', 'easy', 2),

-- Q16: hard / L4 — Evaluate grouping election to convert rental losses to nonpassive
(6, 'Passive Activity and At-Risk Rules', 'A CPA is advising Montoya, who owns three activities: a law practice (1,200 hours of participation), a rental office building leased to the law practice (150 hours), and a passive coffee shop investment (50 hours, generating $40,000 passive income). Montoya has $55,000 of rental losses from the office building. She is considering grouping the rental with the law practice under Treas. Reg. 1.469-4. Evaluate whether the grouping election is advisable.', '["Advisable, because grouping converts the rental into part of a single activity in which Montoya materially participates, making the $55,000 loss nonpassive", "Not advisable, because rental activities can never be grouped with non-rental trade or business activities", "Advisable, because grouping eliminates the passive activity rules for all three activities", "Not advisable, because the self-rental rule already recharacterizes the rental income as nonpassive, providing the same benefit"]'::jsonb, 0, 'Under IRC Section 469 and Treas. Reg. 1.469-4(d)(1), a rental activity may be grouped with a trade or business when each owner has the same proportionate ownership. By grouping, the combined activity is a trade or business in which Montoya materially participates, making the $55,000 rental loss nonpassive. Choice D is incorrect because the self-rental rule only recharacterizes rental income as nonpassive — it does not reclassify rental losses, so grouping provides an additional benefit.', 'hard', 4),

-- Q17: hard / L4 — Assess NIIT impact on passive income
(6, 'Passive Activity and At-Risk Rules', 'A CPA is preparing the 2026 return for Ellison, who has $280,000 of wages, $50,000 of passive rental income, $18,000 of passive losses from a limited partnership, and $22,000 of dividends. Ellison''s modified AGI is $340,000 and she files as single (NIIT threshold $200,000). Assess the net investment income tax under Section 1411.', '["$0, because passive income netted against passive losses is excluded from net investment income", "$1,216, because only the $32,000 net passive income is subject to the 3.8% NIIT", "$836, because only the $22,000 of dividends is subject to the 3.8% NIIT", "$2,052, because net investment income of $54,000 — including $32,000 net passive income and $22,000 dividends — is subject to the 3.8% NIIT"]'::jsonb, 3, 'Under IRC Section 1411, net investment income includes passive activity income (net of passive losses) and portfolio income such as dividends. Ellison''s NII is $54,000 ($50,000 minus $18,000 plus $22,000). The 3.8% NIIT applies to the lesser of NII ($54,000) or MAGI over $200,000 ($140,000), yielding $2,052. Choice B is incorrect because it excludes the $22,000 of dividends, which are also net investment income subject to the NIIT.', 'hard', 4),

-- Q18: easy / L1 — $25,000 special allowance definition
(6, 'Passive Activity and At-Risk Rules', 'Under IRC Section 469(i), what is the special allowance for rental real estate activities?', '["A $25,000 deduction available to all taxpayers who own rental property", "A $25,000 exclusion of rental income from gross income", "A $25,000 allowance permitting active participants to deduct rental losses against nonpassive income", "A $25,000 credit for rehabilitation of rental properties"]'::jsonb, 2, 'Under IRC Section 469(i), taxpayers who actively participate in rental real estate activities may deduct up to $25,000 of rental losses against nonpassive income, subject to phase-out beginning at $100,000 AGI. Choice A is incorrect because the allowance requires active participation — the taxpayer must own at least 10% and make management decisions such as approving tenants or setting rental terms.', 'easy', 1),

-- Q19: easy / L1 — Active participation standard
(6, 'Passive Activity and At-Risk Rules', 'Under Section 469(i), what does active participation in a rental real estate activity require?', '["Making management decisions such as approving tenants and setting rental terms, with at least a 10% ownership interest", "Spending at least 500 hours per year on the rental activity", "Holding a general partnership interest or working interest in the property", "Qualifying as a real estate professional under Section 469(c)(7)"]'::jsonb, 0, 'Under IRC Section 469(i)(6), active participation requires owning at least 10% and participating in management decisions in a bona fide sense, such as approving tenants, setting rental terms, or authorizing repairs. This is a lower standard than material participation. Choice B is incorrect because 500 hours is one test for material participation under the Section 469 regulations, not the standard for active participation, which has no specific hourly requirement.', 'easy', 1),

-- Q20: hard / L4 — Evaluate electing out of installment method on passive activity sale
(6, 'Passive Activity and At-Risk Rules', 'A tax advisor is counseling Drake, who plans to sell a passive activity with $150,000 of suspended losses to an unrelated buyer for $400,000 (basis $250,000). The buyer will pay $100,000 at closing and $100,000 annually for three years. Drake is in the 35% bracket and expects his rate to remain stable. Evaluate whether Drake should elect out of the installment method under Section 453(d).', '["Do not elect out, because the installment method defers the gain while releasing suspended losses proportionally each year", "Elect out, because recognizing the full $150,000 gain immediately releases all $150,000 of suspended losses in the current year, producing a net zero tax impact", "Do not elect out, because electing out converts the gain from capital to ordinary income", "Elect out, because the installment method permanently disallows a portion of the suspended losses"]'::jsonb, 1, 'Under IRC Section 469(g)(3), installment sales release suspended losses proportionally. By electing out under Section 453(d), the full $150,000 gain is recognized immediately, triggering release of all $150,000 of suspended losses under Section 469(g)(1). The gain and losses offset, producing net zero current-year tax while eliminating $150,000 of deferred gain. Choice A is incorrect because deferring the gain also defers the loss release, providing no net time-value benefit since both sides are deferred equally.', 'hard', 4),

-- Q21: easy / L1 — Passive activity credit limitation
(6, 'Passive Activity and At-Risk Rules', 'Under IRC Section 469(d)(2), how are tax credits from passive activities treated?', '["They offset tax liability from any source of income without limitation", "They are permanently disallowed and cannot be carried forward", "They offset tax liability from both passive and portfolio income", "They offset only the tax liability attributable to passive income"]'::jsonb, 3, 'Under IRC Section 469(d)(2), credits from passive activities can only offset the tax allocable to passive income. Excess credits are suspended and carried forward to future years when the taxpayer has sufficient passive income tax liability. Choice A is incorrect because passive credits face the same ring-fencing as passive losses — they cannot offset tax on wages, portfolio income, or other nonpassive sources.', 'easy', 1),

-- Q22: medium / L3 — At-risk recapture when debt character changes
(6, 'Passive Activity and At-Risk Rules', 'Valdez invested $100,000 cash and has a $60,000 qualified recourse loan in a business activity, giving her an initial at-risk amount of $160,000. She deducted $140,000 of losses in prior years, leaving an at-risk amount of $20,000. In 2026, the recourse lender is acquired by Valdez''s brother, making the $60,000 loan related-party nonrecourse debt. Analyze the effect under Section 465.', '["No effect, because the loan principal did not change", "The at-risk amount decreases to $20,000, but no recapture is required until disposition", "The at-risk amount drops to negative $40,000, requiring Valdez to include $40,000 as income under Section 465(e)", "The at-risk amount drops to $0, and only future losses are limited"]'::jsonb, 2, 'Under IRC Section 465(b)(3), nonrecourse financing from a related party is excluded from the at-risk amount. When the loan becomes related-party nonrecourse, the $60,000 is removed, dropping the at-risk amount from $20,000 to negative $40,000. Under Section 465(e), Valdez must recapture $40,000 as income because the at-risk amount fell below zero. Choice D is incorrect because Section 465(e) requires immediate income recognition — it does not simply cap future losses.', 'medium', 3),

-- Q23: medium / L3 — Limited partner material participation test restrictions
(6, 'Passive Activity and At-Risk Rules', 'Romero is a limited partner in a commercial real estate development partnership. During 2026, she spends 450 hours reviewing financial reports, attending quarterly investor meetings, and consulting with the general partner on leasing decisions. Under the Section 469 regulations, analyze whether Romero materially participates.', '["Yes, because 450 hours exceeds the 100-hour threshold for significant participation", "No, because limited partners can only satisfy material participation through the 500-hour test, the 5-of-10-years test, or the personal service activity test", "Yes, because she participates in management decisions, which constitutes material participation for limited partners", "No, because limited partners are permanently barred from material participation regardless of hours spent"]'::jsonb, 1, 'Under IRC Section 469(h)(2) and Treas. Reg. 1.469-5T(e), a limited partner can establish material participation only through three of the seven tests: the 500-hour test, material participation in 5 of 10 preceding years, or the personal service activity test. Romero''s 450 hours fails the 500-hour test, and the other available tests do not apply. Choice D is incorrect because limited partners are not permanently barred — they can materially participate if they meet one of the three available tests, such as 500 or more hours.', 'medium', 3),

-- Q24: hard / L4 — Evaluate pre-retirement disposition strategy for suspended losses
(6, 'Passive Activity and At-Risk Rules', 'A CPA is advising Henderson, age 63, who has $200,000 of accumulated suspended passive losses from rental properties and plans to retire in two years. Upon retirement, income will drop from $350,000 to $80,000 (pension). Henderson is considering: (1) selling all rentals before retirement, or (2) holding through retirement when lower AGI may activate the $25,000 special allowance. Evaluate the better strategy.', '["Sell before retirement, because a complete taxable disposition releases all $200,000 against current high-bracket income", "Hold through retirement, because the lower AGI will activate the $25,000 allowance and gradually absorb the losses", "Sell before retirement, because suspended losses expire when AGI drops below $100,000", "Hold through retirement, because the $25,000 allowance increases to $50,000 for retirees"]'::jsonb, 0, 'Under IRC Section 469(g)(1), selling all rental properties in fully taxable dispositions releases all $200,000 of suspended losses in the sale year, allowing them to offset $350,000 income at the 37% bracket. Using the $25,000 allowance would take 8 years at a lower marginal rate. Choice B is incorrect because the time-value disadvantage and lower marginal rate of absorbing losses at $25,000 per year makes lump-sum release far more beneficial at current high-bracket income.', 'hard', 4),

-- Q25: easy / L1 — Former passive activity definition
(6, 'Passive Activity and At-Risk Rules', 'Under IRC Section 469, what is a former passive activity?', '["An activity that has been permanently disposed of by the taxpayer", "An activity that has never generated passive income or losses", "An activity that was passive in a prior year but in which the taxpayer now materially participates", "An activity reclassified from passive to portfolio by the IRS"]'::jsonb, 2, 'Under IRC Section 469(f), a former passive activity is one that is not passive for the current year but was passive in a prior taxable year, typically because the taxpayer began materially participating. Suspended losses from the former passive period remain and can offset income from that same activity. Choice A is incorrect because a disposed activity is not a former passive activity — it is subject to the disposition rules of Section 469(g).', 'easy', 1),

-- Q26: medium / L2 — Grouping election irrevocability
(6, 'Passive Activity and At-Risk Rules', 'Crawford grouped her restaurant and catering businesses as a single activity in 2023 under Treas. Reg. 1.469-4. In 2026, she wants to separate them because the catering business generates passive income she could use to offset losses from a new rental property. Under the grouping rules, what is the result?', '["Crawford can freely regroup activities each year based on tax benefit", "Crawford cannot separate the activities unless there has been a material change in facts and circumstances making the grouping clearly inappropriate", "Crawford must wait five years before changing any grouping election", "Crawford can separate the activities by filing an amended return for 2023"]'::jsonb, 1, 'Under IRC Section 469 and Treas. Reg. 1.469-4(e), once activities are grouped, the grouping may only be changed if the original grouping is clearly inappropriate or if a material change in facts and circumstances makes the existing grouping clearly inappropriate. A taxpayer cannot regroup solely for tax benefit. Choice A is incorrect because the regulations specifically prevent annual regrouping to manipulate passive income and loss netting.', 'medium', 2),

-- Q27: medium / L3 — Section 1031 exchange does not release suspended losses
(6, 'Passive Activity and At-Risk Rules', 'Kessler owns a rental property — a passive activity — with $75,000 of suspended passive losses. She exchanges it for a like-kind replacement property under Section 1031 with no boot received. Her basis in the old property was $200,000 and the replacement property is valued at $320,000. Analyze the effect of the exchange on Kessler''s suspended passive losses.', '["The $75,000 remains suspended and carries over to the replacement property because a Section 1031 exchange is not a fully taxable disposition", "The $75,000 is released because any disposition triggers suspended loss release under Section 469(g)", "The $75,000 is permanently disallowed because like-kind exchanges reset all tax attributes", "The $75,000 is added to the basis of the replacement property"]'::jsonb, 0, 'Under IRC Section 469(g)(1), suspended passive losses are released only upon a fully taxable disposition to an unrelated party. A Section 1031 like-kind exchange is not a taxable disposition, so the $75,000 of suspended losses remains suspended and continues to be associated with the replacement property. Choice B is incorrect because Section 469(g)(1)(A) requires gain or loss recognition — a tax-deferred exchange does not qualify for suspended loss release.', 'medium', 3),

-- Q28: medium / L3 — Personal service corporation strict passive activity treatment
(6, 'Passive Activity and At-Risk Rules', 'Ridgemont Consulting Inc. is a personal service corporation owned entirely by Dr. Patel. During 2026, the PSC earns $500,000 of consulting income and has $80,000 of passive losses from a rental property it owns. Analyze how the passive activity rules apply to Ridgemont Consulting''s passive losses.', '["The losses offset the consulting income because corporations are exempt from passive activity rules", "The losses offset up to $25,000 of consulting income under the special rental allowance", "The losses offset the consulting income because closely held C corporations can use passive losses against active income", "The losses can only offset passive income because personal service corporations are subject to the same passive activity limitation as individuals"]'::jsonb, 3, 'Under IRC Section 469(a)(2), personal service corporations are subject to passive activity rules in the same manner as individuals — passive losses can only offset passive income. Unlike closely held C corporations that can offset active business income under Section 469(e)(2), PSCs receive no special netting benefit. Choice C is incorrect because it describes the closely held C corporation rule, not the stricter PSC limitation.', 'medium', 3),

-- Q29: medium / L2 — Extraordinary personal services rental exception
(6, 'Passive Activity and At-Risk Rules', 'Sullivan operates a medical imaging center through an LLC. The center provides MRI and CT equipment to patients, but board-certified radiologists perform and interpret all scans on-site. Sullivan participates for 900 hours during 2026. Under Treas. Reg. 1.469-1T(e)(3)(ii), how is this activity classified?', '["As a rental activity because patients pay for the use of tangible imaging equipment", "As a passive rental activity eligible for the $25,000 special allowance", "As a trade or business activity because extraordinary personal services are provided in connection with the property use", "As a portfolio activity generating investment income from medical equipment"]'::jsonb, 2, 'Under IRC Section 469 and Treas. Reg. 1.469-1T(e)(3)(ii)(B), an activity is not a rental activity if extraordinary personal services are provided in connection with making property available for customer use. Medical imaging with professional radiologist interpretation qualifies as extraordinary personal services, making this a trade or business activity. Choice A is incorrect because the extraordinary personal services exception removes the activity from rental classification even though equipment use is a significant component.', 'medium', 2),

-- Q30: medium / L2 — Low-income housing credit special phase-out threshold
(6, 'Passive Activity and At-Risk Rules', 'Tanaka invests in a qualified low-income housing project placed in service in 2024 and receives $18,000 of passive tax credits in 2026. Her AGI is $180,000 and she has no passive income. Under IRC Section 469(i)(6)(B), how much of the credit can Tanaka use against her nonpassive income tax?', '["$0, because passive credits cannot offset nonpassive tax liability when there is no passive income", "$0, because the $25,000-equivalent credit allowance is fully phased out at AGI over $150,000", "Up to the deduction-equivalent of $25,000, because the low-income housing credit phase-out threshold is $200,000 and Tanaka''s AGI is below it", "Only a portion, based on the standard $100,000 AGI phase-out threshold for rental allowances"]'::jsonb, 2, 'Under IRC Section 469(i)(6)(B), the special $25,000-equivalent allowance for low-income housing credits placed in service after 1989 uses a $200,000 AGI phase-out threshold instead of the standard $100,000. Because Tanaka''s AGI of $180,000 is below $200,000, she receives the full credit allowance. Choice B is incorrect because it applies the $150,000 phase-out ceiling from the standard rental loss allowance rather than the special $200,000 threshold for post-1989 low-income housing credits.', 'medium', 2)
;

COMMIT;
